/*
 * Smartmenus "More" 
 * Based on: https://www.smartmenus.org/forums/topic/more-option-for-desktop-menu/#post-3015
 * Standalone vanilla JavaScript version (no SmartMenus dependency)
 */

(function() {
	'use strict';

	// Helper functions
	function hasClass(element, className) {
		return element && element.classList.contains(className);
	}

	function getWindowWidth() {
		return window.innerWidth || document.documentElement.clientWidth;
	}

	function getComputedStyleProperty(element, property) {
		return window.getComputedStyle(element).getPropertyValue(property);
	}

	// Find all navigation menus that should have the "More" functionality
	function findNavMenus() {
		// Primary navigation menu selectors
		// Based on lib/nav.php structure: <ul id="menu-dropdowns" class="nav navbar-nav ...">
		var selectors = [
			'#menu-dropdowns',                    // Specific ID for primary menu
			'ul.nav.navbar-nav',                  // Primary menu structure
			'ul.navbar-nav'                       // More general primary menu
		];

		var menus = [];
		selectors.forEach(function(selector) {
			var elements = document.querySelectorAll(selector);
			Array.prototype.forEach.call(elements, function(el) {
				// Only add if:
				// - Not already added
				// - Not collapsible (mobile menu)
				// - Not the secondary header nav (#nav-secondary)
				// - Is inside a .site-nav container (primary navigation)
				var isSecondaryNav = el.closest('#nav-secondary') !== null;
				var isPrimaryNav = el.closest('.site-nav') !== null || el.id === 'menu-dropdowns';
				
				if (menus.indexOf(el) === -1 && 
				    !hasClass(el, 'sm-collapsible') && 
				    !isSecondaryNav && 
				    isPrimaryNav) {
					menus.push(el);
				}
			});
		});

		return menus;
	}

	// Initialize "More" functionality for a single menu
	function initOverflowingNavbar(rootElement) {
		if (!rootElement || hasClass(rootElement, 'sm-collapsible')) {
			return;
		}

		// Get original menu items (only direct LI children)
		var originalItems = Array.from(rootElement.children).filter(function(child) {
			return child.tagName === 'LI';
		});

		if (originalItems.length === 0) {
			return;
		}

		// Clone root menu for "More" submenu
		var moreSub = rootElement.cloneNode(true);
		moreSub.removeAttribute('id');
		moreSub.className = 'dropdown-menu';

		// Get items from cloned submenu
		var moreSubItems = Array.from(moreSub.children).filter(function(child) {
			return child.tagName === 'LI';
		});

		// Create "More" menu item
		var moreItem = document.createElement('li');
		moreItem.className = 'dropdown nav-item';
		
		var moreLink = document.createElement('a');
		moreLink.className = 'nav-link';
		moreLink.href = 'javascript:void(0);';
		moreLink.textContent = 'More ';
		
		var caret = document.createElement('span');
		caret.className = 'caret';
		moreLink.appendChild(caret);
		
		moreItem.appendChild(moreLink);
		moreItem.appendChild(moreSub);

		var viewportW = null;
		var hiddenItems = [];
		var hiddenMoreItems = [];

		// Find first link for layout detection
		var firstLink = rootElement.querySelector('a');
		var firstLinkParent = firstLink ? firstLink.parentElement : null;

		function handleResize(force) {
			var curWidth = getWindowWidth();

			if (viewportW !== curWidth || force) {
				// Hide More item
				if (moreItem.parentNode) {
					moreItem.parentNode.removeChild(moreItem);
				}

				// Show all main menu items
				hiddenItems.forEach(function(item) {
					rootElement.appendChild(item);
				});
				hiddenItems = [];

				// Show all More sub items
				hiddenMoreItems.forEach(function(item) {
					moreSub.insertBefore(item, moreSub.firstChild);
				});
				hiddenMoreItems = [];

				// Check if in desktop view and the last item is wrapped
				var isDesktopView = !hasClass(rootElement, 'sm-collapsible');
				
				if (firstLinkParent) {
					var firstLinkParentStyle = window.getComputedStyle(firstLinkParent);
					var floatValue = firstLinkParentStyle.float;
					var displayValue = firstLinkParentStyle.display;
					var flexDirection = firstLinkParentStyle.flexDirection;

					isDesktopView = isDesktopView && (
						/^(left|right)$/.test(floatValue) || 
						displayValue === 'table-cell' || 
						flexDirection === 'row'
					);
				}

				var firstItemTop = originalItems.length > 0 ? originalItems[0].offsetTop : 0;
				var lastItemTop = originalItems.length > 0 ? originalItems[originalItems.length - 1].offsetTop : 0;
				var isWrapped = lastItemTop !== firstItemTop;

				if (isDesktopView && isWrapped) {
					// Show More item
					rootElement.appendChild(moreItem);

					// While the More item is wrapped, move items to hiddenItems
					var maxIterations = 100; // Safety limit
					var iterations = 0;
					while (moreItem.offsetTop !== firstItemTop && iterations < maxIterations) {
						iterations++;
						var prevSibling = moreItem.previousElementSibling;
						if (prevSibling && prevSibling.tagName === 'LI') {
							hiddenItems.unshift(prevSibling);
							prevSibling.parentNode.removeChild(prevSibling);
						} else {
							break; // Safety break to prevent infinite loop
						}
					}

					// Hide proper More sub items
					var itemsToHide = moreSubItems.length - hiddenItems.length;
					for (var i = 0; i < itemsToHide; i++) {
						if (moreSubItems[i] && moreSubItems[i].parentNode) {
							hiddenMoreItems.unshift(moreSubItems[i]);
							moreSubItems[i].parentNode.removeChild(moreSubItems[i]);
						}
					}
				}

				// Save new viewport width
				viewportW = curWidth;
			}
		}

		// Initial resize handling (with slight delay to ensure layout is ready)
		setTimeout(function() {
			handleResize();
		}, 0);

		// Window load event
		function handleLoad() {
			handleResize(true);
		}

		// Window resize event (with debouncing for performance)
		var resizeTimeout;
		function handleResizeEvent() {
			clearTimeout(resizeTimeout);
			resizeTimeout = setTimeout(function() {
				handleResize();
			}, 100);
		}

		// Bind events
		window.addEventListener('load', handleLoad);
		window.addEventListener('resize', handleResizeEvent);
	}

	// Initialize all menus when DOM is ready
	function init() {
		var menus = findNavMenus();
		menus.forEach(function(menu) {
			initOverflowingNavbar(menu);
		});
	}

	// Initialize when DOM is ready
	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', init);
	} else {
		// DOM is already ready
		init();
	}

	// Also re-initialize after a short delay to catch dynamically loaded menus
	setTimeout(init, 500);

})();
